(function () {
  'use strict';

  // If QRCode is already defined (e.g. a real vendor file was swapped in), do nothing.
  if (typeof window !== 'undefined' && window.QRCode) return;

  // Runtime CDN fallback — loads asynchronously.
  // QRPrint defers rendering until window.QRCode is available.
  var script = document.createElement('script');
  script.src = 'https://cdn.jsdelivr.net/npm/qrcode@1.5.4/build/qrcode.min.js';
  script.async = false;
  script.onerror = function () {
    console.warn('[qrcode.min.js] CDN load failed — QR printing will not work offline.');
  };
  document.head.appendChild(script);
})();
